<div class="d-flex justify-content-between align-items-center mb-4"><div><h4 class="fw-bold mb-1">Receive Purchase Order</h4><p class="text-muted mb-0"><?php echo htmlspecialchars($order['po_number'] ?? ''); ?> · <?php echo htmlspecialchars($order['supplier'] ?? 'Supplier'); ?></p></div><a class="btn btn-outline-secondary" href="/ERP/public/management/procurement">Back to Procurement</a></div>
<?php if (!empty($_SESSION['procurement_flash'])): ?><div class="alert alert-info"><?php echo htmlspecialchars($_SESSION['procurement_flash']); unset($_SESSION['procurement_flash']); ?></div><?php endif; ?>
<form method="post" action="/ERP/public/management/procurement/receive/save"><input type="hidden" name="purchase_order_id" value="<?php echo (int)$order['id']; ?>"><div class="card shadow-sm border-0"><div class="card-body"><h5 class="fw-bold mb-3">Goods received</h5><div class="table-responsive"><table class="table align-middle"><thead><tr><th>PO item</th><th>Ordered</th><th>Inventory item</th><th>Quantity received</th><th>Price rate</th></tr></thead><tbody><?php foreach (($order['items'] ?? []) as $item): ?><tr><td><?php echo htmlspecialchars($item['product_name']); ?></td><td><?php echo number_format((float)$item['quantity'], 2); ?></td><td><select class="form-select" name="items[<?php echo (int)$item['id']; ?>][inventory_item_id]" required><option value="">Select inventory item</option><?php foreach ($inventoryItems as $inventoryItem): ?><option value="<?php echo (int)$inventoryItem['id']; ?>" <?php echo strcasecmp(trim((string)$inventoryItem['name']), trim((string)$item['product_name'])) === 0 ? 'selected' : ''; ?>><?php echo htmlspecialchars($inventoryItem['item_code'] . ' - ' . $inventoryItem['name']); ?></option><?php endforeach; ?></select></td><td><input class="form-control" type="number" name="items[<?php echo (int)$item['id']; ?>][quantity_received]" min="0" max="<?php echo (float)$item['quantity']; ?>" step="0.01" value="<?php echo (float)$item['quantity']; ?>" required></td><td><input class="form-control" type="number" name="items[<?php echo (int)$item['id']; ?>][price_rate]" min="0" step="0.01" value="<?php echo htmlspecialchars((string)$item['price_rate']); ?>" required></td></tr><?php endforeach; ?></tbody></table></div><button class="btn btn-success" type="submit"><i class="bi bi-box-arrow-in-down me-1"></i>Record Receipt and Update Inventory</button></div></div></form>
